<?php
/**  * Enhanced Service Type → Required Parts API  * Endpoint for joborder.php auto-populate with merchandise validation  *  * GET ?action=get_parts&service_types=Oil Change,Tire Repair  * → Returns grouped parts by category from service_type_inventory_mapping  * → Validates merchandise parts against inventory_products table  */  ob_start();
header('Content-Type: application/json');  require_once __DIR__ . '/../../backend/lib.php';
require_once __DIR__ . '/../../public/db_connect.php';  try {  $pdo = get_db_connection();  if (!$pdo) {  throw new Exception('Database connection failed');  }
} catch (Exception $e) {  echo json_encode([  'success' => false,  'error' => 'Database connection error: ' . $e->getMessage()  ]);  exit;
}
$action = $_GET['action'] ?? '';
$service_types_str = $_GET['service_types'] ?? '';  if ($action !== 'get_parts') {  http_response_code(400);  echo json_encode(['success' => false, 'error' => 'Invalid action']);  exit;
}  if (empty($service_types_str)) {  echo json_encode([  'success' => true,  'data' => [],  'message' => 'Please select service type',  'count' => 0  ]);  exit;
}  // Parse comma-separated service types
$service_types = array_filter(array_map('trim', explode(',', $service_types_str)));
if (empty($service_types)) {  echo json_encode([  'success' => true,  'data' => [],  'message' => 'No valid service types provided',  'count' => 0  ]);  exit;
}  // Check if table has data and populate if empty (with timeout protection)
try {  // First ensure table exists  $pdo->exec("  CREATE TABLE IF NOT EXISTS service_type_inventory_mapping (  id INT AUTO_INCREMENT PRIMARY KEY,  service_type VARCHAR(100) NOT NULL,  required_part VARCHAR(200) NOT NULL,  part_category VARCHAR(50) DEFAULT 'General',  sort_order INT DEFAULT 0,  is_merchandise BOOLEAN DEFAULT TRUE,  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  UNIQUE KEY unique_service_part (service_type, required_part),  INDEX idx_service_type (service_type),  INDEX idx_part_category (part_category),  INDEX idx_sort_order (sort_order)  )  ");  $stmt = $pdo->query("SELECT COUNT(*) as count FROM service_type_inventory_mapping");  $count = $stmt->fetch(PDO::FETCH_ASSOC)['count'];  if ($count == 0) {  // Get actual service types from database to ensure names match  $actual_service_types = [];  try {  $stmt = $pdo->query("SELECT service_name FROM job_order_service_types WHERE active = TRUE ORDER BY sort_order");  $actual_service_types = $stmt->fetchAll(PDO::FETCH_COLUMN);  } catch (Exception $e) {  // If query fails, use default service names  $actual_service_types = ['Oil Change', 'Tire Repair', 'Calibration', 'General Maintenance', 'Engine Repair', 'Brake Service', 'Electrical', 'Air Conditioning', 'Transmission Service', 'Suspension Repair', 'Wheel Alignment', 'Battery Replacement', 'Diagnostic Check', 'Detailing / Cleaning', 'Other'];  }  // Service type parts mapping that matches database service names  $exact_data = [];  foreach ($actual_service_types as $service_name) {  switch ($service_name) {  case 'Oil Change':  $exact_data[$service_name] = [  'Merchandise' => [  'Engine Oil – HD 30',  'Engine Oil – HD 40',  'Engine Oil – Ultron Touring',  'Engine Oil – Blaze Racing',  'Engine Oil – MO 30',  'Engine Oil – MO 40',  'Oil Filter – Nomis',  'Oil Filter – VIC',  'Oil Filter – Sakura',  'Oil Filter – C‑series filters',  'Gasket Maker'  ]  ];  break;  case 'Tire Repair':  $exact_data[$service_name] = [  'Merchandise' => [  'Tire Valve Rubber',  'Tire Valve Steel',  'MP1 Patch (Med)',  'MP2 Patch (Large)',  'CT20 Radial Patch',  'Valkarn Cement'  ]  ];  break;  case 'Calibration':  $exact_data[$service_name] = [  'Merchandise' => [  'Hydrotur (oil/lube)',  'MP Grease (sealant)',  'Standard Gauge (from accessories)'  ]  ];  break;  case 'General Maintenance':  $exact_data[$service_name] = [  'Merchandise' => [  'MP Grease',  'WD‑40',  'Petromate Penetrating Oil',  'Armor All (Small/Big)',  'VS1 Protector (Small/Big)',  'Chamois/Kanebo'  ]  ];  break;  case 'Engine Repair':  $exact_data[$service_name] = [  'Merchandise' => [  'Engine Oil – HD series',  'Engine Oil – Ultron',  'Engine Oil – Blaze Racing',  'Engine Oil – Trekker',  'Oil Filter – Nomis',  'Oil Filter – VIC',  'Oil Filter – Sakura',  'Oil Filter – C‑series filters',  'Coolant – Regular',  'Coolant – Green',  'Coolant – Pink',  'Gasket Maker'  ]  ];  break;  case 'Brake Service':  $exact_data[$service_name] = [  'Merchandise' => [  'Brake Fluid 900ml',  'Brake Fluid Med',  'Brake Fluid Small',  'Break Cleaner Hardex'  ]  ];  break;  case 'Electrical':  $exact_data[$service_name] = [  'Merchandise' => [  'WD‑40',  'Petromate Penetrating Oil',  'MP Grease (for terminals)'  ]  ];  break;  case 'Air Conditioning':  $exact_data[$service_name] = [  'Merchandise' => [  'Coolant Green',  'Coolant Pink',  'AC Filter (Oil/Fuel Filter variants)',  'O‑rings (from accessories)'  ]  ];  break;  case 'Transmission Service':  $exact_data[$service_name] = [  'Merchandise' => [  'ATF Premium',  'ATF HTF',  'Transmission Filter (Fuel/Oil Filter variants)',  'Gasket Maker'  ]  ];  break;  case 'Suspension Repair':  $exact_data[$service_name] = [  'Merchandise' => [  'MP Grease (for bushings/ball joints)',  'Shock Absorber (if stocked)'  ]  ];  break;  case 'Wheel Alignment':  $exact_data[$service_name] = [  'Merchandise' => [  'Tire Valve Rubber',  'Tire Valve Steel',  'Alignment Bolts/Wheel Weights (from accessories)'  ]  ];  break;  case 'Battery Replacement':  $exact_data[$service_name] = [  'Merchandise' => [  'Car Battery (if stocked under accessories)',  'MP Grease (small packs for terminals)'  ]  ];  break;  case 'Diagnostic Check':  $exact_data[$service_name] = [  'Merchandise' => [  'OBD Scanner (tool, if stocked)',  'Diagnostic Printout Paper (office supply)'  ]  ];  break;  case 'Detailing / Cleaning':  $exact_data[$service_name] = [  'Merchandise' => [  'Clean N Shine Shampoo',  'Armor All (Small/Big)',  'Tire Black (Small/Big)',  'Chamois/Kanebo',  'Air Freshener – Neo Shaldan',  'Air Freshener – California Scents',  'Air Freshener – Little Trees',  'Air Freshener – Glade Spray'  ]  ];  break;  case 'Other':  $exact_data[$service_name] = [  'Merchandise' => [  'Staff encode manually kung wala sa list'  ]  ];  break;  default:  // For any other service types, provide a basic mapping  $exact_data[$service_name] = [  'Merchandise' => [  'MP Grease',  'WD‑40',  'Gasket Maker'  ]  ];  break;  }  }  // Insert exact data with proper sort order - all parts are merchandise  foreach ($exact_data as $service_type => $categories) {  $sort_order = 1;  foreach ($categories as $category => $parts) {  foreach ($parts as $part) {  try {  // All parts are merchandise as specified  $is_merchandise = 1;  $stmt = $pdo->prepare("  INSERT IGNORE INTO service_type_inventory_mapping  (service_type, required_part, part_category, sort_order, is_merchandise)  VALUES (?, ?, ?, ?, ?)  ");  $stmt->execute([$service_type, $part, $category, $sort_order++, $is_merchandise]);  } catch (Exception $e) {  // Ignore duplicate errors  }  }  }  }  }
} catch (Exception $e) {  // Continue with query even if count check fails
}  // Query service_type_inventory_mapping table with merchandise validation
try {  $sql = "  SELECT DISTINCT  service_type,  required_part,  part_category,  sort_order,  is_merchandise  FROM service_type_inventory_mapping  WHERE service_type IN (".str_repeat('?,', count($service_types) - 1)." ?)  ORDER BY service_type, sort_order  ";  $stmt = $pdo->prepare($sql);  $stmt->execute($service_types);  $all_parts = $stmt->fetchAll(PDO::FETCH_ASSOC);  if ($stmt->errorCode() !== '00000') {  throw new Exception('Database query failed: ' . implode(' ', $stmt->errorInfo()));  }
} catch (Exception $e) {  echo json_encode([  'success' => false,  'error' => 'Query error: ' . $e->getMessage()  ]);  exit;
}  if (empty($all_parts)) {  echo json_encode([  'success' => true,  'data' => [],  'message' => 'No parts found for selected service types',  'matched_services' => 0,  'total_parts' => 0  ]);  exit;
}  // Get merchandise products from inventory_products for validation
$merchandise_products = [];
try {  $stmt = $pdo->query("SELECT product_name, category FROM inventory_products ORDER BY product_name");  $products = $stmt->fetchAll(PDO::FETCH_ASSOC);  foreach ($products as $product) {  $merchandise_products[strtolower($product['product_name'])] = $product['category'];  }
} catch (Exception $e) {  // If inventory_products doesn't exist, continue without validation  $merchandise_products = [];
}  // Group parts by part_category and validate merchandise
$grouped_parts = [];
$matched_services = array_unique(array_column($all_parts, 'service_type'));
$total_parts = count($all_parts);
$validated_parts = 0;
$non_merchandise_parts = 0;  foreach ($all_parts as $part) {  $category = $part['part_category'] ?: 'General';  if (!isset($grouped_parts[$category])) {  $grouped_parts[$category] = [];  }  $part_info = [  'name' => $part['required_part'],  'is_merchandise' => (bool)$part['is_merchandise'],  'in_inventory' => false  ];  // Validate if merchandise part exists in inventory  if ($part['is_merchandise']) {  $part_name_lower = strtolower($part['required_part']);  $found_in_inventory = false;  // Check exact match first  if (isset($merchandise_products[$part_name_lower])) {  $found_in_inventory = true;  } else {  // Check partial matches for flexible matching  foreach ($merchandise_products as $inventory_name => $inventory_category) {  if (strpos($inventory_name, $part_name_lower) !== false ||  strpos($part_name_lower, $inventory_name) !== false) {  $found_in_inventory = true;  break;  }  }  }  $part_info['in_inventory'] = $found_in_inventory;  if ($found_in_inventory) {  $validated_parts++;  }  } else {  $non_merchandise_parts++;  $part_info['in_inventory'] = true; // Non-merchandise items are considered valid  }  $grouped_parts[$category][] = $part_info;
}  echo json_encode([  'success' => true,  'data' => $grouped_parts,  'message' => 'Parts loaded successfully',  'matched_services' => count($matched_services),  'service_types_matched' => $matched_services,  'total_parts' => $total_parts,  'validated_merchandise' => $validated_parts,  'non_merchandise' => $non_merchandise_parts,  'inventory_validation' => !empty($merchandise_products)
], JSON_UNESCAPED_UNICODE);  exit;
?>  